/* ============================================================
   backgrounds.js — the pictures you can put behind everything.

   Each one is embedded, because Quire ships as a single file that has to
   work with no network and no folder of assets beside it. To add another:
   drop a new entry in the list with an `id`, a `name`, an `ink` and a data
   URI, and it appears in Settings. Nothing else needs touching.

   They are stored at a size that suits what they are for. A background sits
   under a scrim, behind blurred glass, and is never looked at directly, so
   paying for detail nobody can see would only make the file heavier to send.

   `ink` and `scrim` answer two different questions, and a picture can answer
   them differently. `ink` is what the picture IS — read from its middle — and
   decides the default. `scrim` is what the writing has to SURVIVE, read from
   the bright end, because a mostly-dark photograph with a white sky in it
   will still swallow small white text wherever that sky falls. Every scrim
   below is set so the brightest twentieth of the picture composites to the
   same dark value, which is why two dark photographs carry different numbers.
   ============================================================ */

export const BACKGROUNDS = [
  {
    id: 'lounge',
    name: 'Lounge',
    ink: 'light',
    scrim: 0.71,
    url: 'data:image/jpeg;base64,',
  },
  {
    id: 'ridge',
    name: 'Ridge',
    ink: 'dark',
    scrim: 0.55,
    url: 'data:image/jpeg;base64,',
  },
  {
    id: 'canopy',
    name: 'Canopy',
    ink: 'dark',
    scrim: 0.65,
    url: 'data:image/jpeg;base64,',
  },
];

/* A journal that already had a background keeps having one. The three
   pictures were replaced, not renamed, so an old id is pointed at the new
   picture in the same slot rather than quietly falling back to none. */
const REPLACED = { highland: 'lounge', fjord: 'ridge', pass: 'canopy' };

export const findBackground = id =>
  BACKGROUNDS.find(b => b.id === id)
  || BACKGROUNDS.find(b => b.id === REPLACED[id])
  || null;

/** How hard a picture has to be held down before small writing sits on it. */
export const scrimFor = bg =>
  (bg && typeof bg.scrim === 'number') ? bg.scrim : (bg && bg.ink === 'light' ? .58 : .45);
